effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float ar = acScreenSize.x / max(acScreenSize.y, 1.0);
  vec2 p = uv * vec2(ar, 1.0) * density + vec2(0.0, acTime * drift * density);
  vec2 g = floor(p);
  vec2 f = fract(p);
  float s = 0.0;
  for (int y = 0; y <= 1; y++){
    for (int x = 0; x <= 1; x++){
      vec2 o = vec2(float(x), float(y));
      float h = gmHash(g + o);
      if (h > 0.72){
        vec2 sp = o + vec2(gmHash(g + o + 5.0), gmHash(g + o + 9.0));
        float d = length(sp - f);
        float tw = 0.6 + 0.4 * sin(acTime * twinkle + h * 30.0);
        s += smoothstep(0.06, 0.0, d) * tw;
      }
    }
  }
  vec3 col = c + vec3(s) * brightness * mixAmt;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
